<?php $title='Galleries'; $active='galleries'; require_once __DIR__ . '/_layout.php'; $rows=db()->query('SELECT g.*, (SELECT COUNT(*) FROM gallery_images i WHERE i.gallery_id=g.id) images FROM galleries g ORDER BY created_at DESC')->fetchAll(); ?>
<div class="topbar"><h1>Galleries</h1><a class="btn" href="gallery_edit.php">+ New gallery</a></div><section class="panel"><table class="table"><tr><th>Title</th><th>Images</th><th>Status</th><th></th></tr><?php foreach($rows as $r): ?><tr><td><?=h($r['title'])?></td><td><?=h($r['images'])?></td><td><?=h($r['status'])?></td><td><a href="gallery_edit.php?id=<?=$r['id']?>">Edit</a></td></tr><?php endforeach; ?></table></section><?php require __DIR__ . '/_footer.php'; ?>
